text:
        // decoding of sub messages, if pruneat is set to a nested part.
        decodeSubMessages: false,
      },
      {
        checkForEncryption: false,
        excludeAttachmentData: !includeRaw,
      }
    );
    return mimeTree;
  }

  get hasEncryptedParts() {
    return this.#hasEncryptedParts;
  }
}

export function getMessagesInFolder(folder) {
  if (folder.isServer) {
    return [];
  }

  if (folder.getFlag(Ci.nsMsgFolderFlags.Virtual)) {
    const messages = [];
    const searchFolders = [];
    const wrappedVirtualFolder =
      lazy.VirtualFolderHelper.wrapVirtualFolder(folder);

    // Check explicitly listed searchFolders and all folders selected by wildcard,
    // if any.
    for (const searchFolder of [
      ...getWildcardVirtualFolders(wrappedVirtualFolder),
      ...wrappedVirtualFolder.searchFolders,
    ]) {
      // Use cached hits or schedule the folder to be searched manually.
      // Note: The cached hits are stored in the db of each search folder using
      // the URI of the virtual folder as identifier.
      const cachedHits = searchFolder.msgDatabase.getCachedHits(folder.URI);
      if (!cachedHits) {
        searchFolders.push(searchFolder);
        continue;
      }
      for (const msg of cachedHits) {
        messages.push(msg);
      }
    }

    for (const searchFolder of searchFolders) {
      const msgs = searchFolder.msgDatabase.getFilterEnumerator(
        wrappedVirtualFolder.searchTerms
      );
      for (const msg of msgs) {
        messages.push(msg);
      }
    }

    return messages;
  }

  // Attempt to read the folder directly.
  try {
    return [...folder.messages];
  } catch (e) {
    // Some folders fail to retrieve messages, instead of returning an empty array.
    console.warn(
      `Failed to retrieve content of folder ${folder.localizedName}: ${e}`
    );
  }

  return [];
}

/**
 * Map() that automatically removes added entries after 60s.
 */
export class TemporaryCacheMap extends Map {
  set(key, value) {
    super.set(key, value);
    // Remove the value from the cache after 60s.
    setTimeout(() => this.delete(key), 1000 * 60);
  }
}

